package co.sena.agendamiento.controller;
import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import java.io.*;import java.time.*;import java.sql.*;import co.sena.agendamiento.service.CitaService;
@WebServlet("/citas") public class CitaServlet extends HttpServlet {
 private final CitaService servicio=new CitaService();
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{try{req.setAttribute("listaCitas",servicio.consultarTodas());req.setAttribute("pacientes",servicio.personas(false));req.setAttribute("medicos",servicio.personas(true));req.setAttribute("mensaje",req.getSession().getAttribute("mensaje"));req.getSession().removeAttribute("mensaje");req.getRequestDispatcher("/WEB-INF/citas.jsp").forward(req,res);}catch(SQLException e){log("Error de consulta",e);res.sendError(500,"Revise la conexión MySQL.");}}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{req.setCharacterEncoding("UTF-8");String mensaje;try{switch(req.getParameter("accion")){case "guardar" -> servicio.guardarCita(Integer.parseInt(req.getParameter("paciente")),Integer.parseInt(req.getParameter("medico")),LocalDateTime.parse(req.getParameter("fecha")));case "estado" -> servicio.actualizarEstado(Integer.parseInt(req.getParameter("id")),req.getParameter("nuevoEstado"));case "eliminar" -> servicio.eliminarCita(Integer.parseInt(req.getParameter("id")));default -> throw new IllegalArgumentException();}mensaje="Operación realizada.";}catch(SQLException e){log("Error de escritura",e);mensaje="No se pudo guardar el cambio. Revise disponibilidad y conexión.";}catch(RuntimeException e){mensaje="Datos inválidos o cita no disponible.";}req.getSession().setAttribute("mensaje",mensaje);res.sendRedirect(req.getContextPath()+"/citas");}
}